//! R481 new map/shape/resource cases only. Uses the unchanged R480 runtime.
use super::{native_multisector_resources::{self,Inputs},native_multisector_runtime::{Runtime,Action,UiPage,UiFrame},native_resources::BytePin};
use std::{path::Path,fs,thread,time::{Duration,Instant},sync::atomic::Ordering};use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn input(name:&str)->Inputs{let p=Path::new(env!("CARGO_MANIFEST_DIR"));let manifest=p.join(format!("logs/continuation-20261003/{name}"));let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(b).into()}}}
#[track_caller]
fn wait(mut f:impl FnMut()->bool){let caller=std::panic::Location::caller();let start=Instant::now();eprintln!("R481 wait begin {caller}");let until=start+Duration::from_secs(90);while !f(){assert!(Instant::now()<until,"R481 bounded wait timeout at {caller}");thread::sleep(Duration::from_millis(5));}eprintln!("R481 wait complete {caller} elapsed_ms={}",start.elapsed().as_millis());}
fn pixels(p:&Path)->Vec<u8>{let mut d=png::Decoder::new(fs::File::open(p).unwrap()).read_info().unwrap();let mut b=vec![0;d.output_buffer_size()];let i=d.next_frame(&mut b).unwrap();assert_eq!(i.color_type,png::ColorType::Rgba);b.truncate(i.buffer_size());b}
fn save(p:&Path,f:&UiFrame)->Value{let rgba:Vec<_>=f.bgra().unwrap().chunks_exact(4).flat_map(|p|[p[2],p[1],p[0],p[3]]).collect();let mut e=png::Encoder::new(fs::File::create(p).unwrap(),800,600);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(&rgba).unwrap();let b=fs::read(p).unwrap();json!({"path":p,"bytes":b.len(),"sha256":format!("{:X}",Sha256::digest(b)),"rgba_sha256":format!("{:X}",Sha256::digest(rgba))})}
fn fixture(root:&Path,m:&Value,name:&str)->Inputs{let path=root.join(name);let b=serde_json::to_vec_pretty(m).unwrap();fs::write(&path,&b).unwrap();Inputs{project:Path::new(env!("CARGO_MANIFEST_DIR")).into(),manifest:path,manifest_pin:BytePin{bytes:b.len() as u64,sha256:Sha256::digest(b).into()}}}
fn close(rt:&mut Runtime){rt.handle(Action::Close).unwrap();wait(||{rt.poll();rt.page()==UiPage::Closed});assert!(rt.progress().retired.load(Ordering::Acquire));}
fn failed(i:Inputs,id:u32)->String{eprintln!("R481 expected load refusal map={id} manifest={}",i.manifest.display());let mut rt=Runtime::start(i).unwrap();wait(||{rt.poll();rt.page()==UiPage::Menu});rt.handle(Action::Select(1,id)).unwrap();rt.handle(Action::Enter).unwrap();wait(||{rt.poll();assert_ne!(rt.page(),UiPage::Preview,"R481 expected load refusal but map{id} produced a preview");rt.page()==UiPage::Menu});assert_eq!(rt.choice().unwrap().map_id,id);assert!(rt.frame().is_none()&&rt.status().contains("載入失敗"));let s=rt.status().to_owned();close(&mut rt);s}
fn output_root()->std::path::PathBuf{
 let base=Path::new(env!("CARGO_MANIFEST_DIR")).join("target/current/scratch/native-multisector-batch");fs::create_dir_all(&base).unwrap();
 for sequence in 0..10_000{let p=base.join(format!("run-{}-{sequence}",std::process::id()));match fs::create_dir(&p){Ok(())=>return p,Err(e)if e.kind()==std::io::ErrorKind::AlreadyExists=>continue,Err(e)=>panic!("create owned batch output: {e}")}}
 panic!("owned batch output directory allocation exhausted")
}
fn unknown_tile_archives(root:&Path,plan:&mut Value){
 // Preserve all member names and the complete original map geometry. Every
 // synthetic member has 256 valid slot offsets and an explicit unknown255 body.
 // No original Tile/Sprite pak is copied or changed.
 let original=fs::read(Path::new(plan["archive_root"].as_str().unwrap()).join("LTtile.idx")).unwrap();
 let count=u32::from_le_bytes(original[..4].try_into().unwrap())as usize;assert_eq!(original.len(),4+28*count);
 let mut member=256u32.to_le_bytes().to_vec();for offset in 0..=256u32{member.extend(offset.to_le_bytes());}member.extend([255u8;256]);
 let mut index=(count as u32).to_le_bytes().to_vec();let mut pak=Vec::new();
 for row in original[4..].chunks_exact(28){index.extend((pak.len()as u32).to_le_bytes());index.extend_from_slice(&row[4..24]);index.extend((member.len()as u32).to_le_bytes());pak.extend_from_slice(&member);}
 let archives=root.join("synthetic-unknown255-archives");fs::create_dir(&archives).unwrap();
 for(name,bytes)in[("LTtile.idx",index),("LTtile.pak",pak),("LTsprite.idx",0u32.to_le_bytes().to_vec()),("LTsprite.pak",vec![0])]{fs::write(archives.join(name),bytes).unwrap();}
 plan["archive_root"]=json!(archives);
 for(name,pin)in["LTtile.idx","LTtile.pak","LTsprite.idx","LTsprite.pak"].into_iter().zip(plan["archives"].as_array_mut().unwrap()){
  let path=archives.join(name);let bytes=fs::read(&path).unwrap();pin["path"]=json!(path);pin["bytes"]=json!(bytes.len());pin["sha256"]=json!(format!("{:X}",Sha256::digest(bytes)));
 }
}
