 let p=Path::new(env!("CARGO_MANIFEST_DIR"));let reference_root=p.join("target/r481-multisector-batch");let root=output_root();let i=input("r481-map-binding.json");let m:Value=serde_json::from_slice(&fs::read(&i.manifest).unwrap()).unwrap();let(_,plans,rows)=native_multisector_resources::load(&i).unwrap();assert_eq!(plans.len(),13);assert_eq!(rows.len(),40);let ids=[551u32,504,526,525,531,529];assert_eq!(plans[7..].iter().map(|b|b.plan.map_id).collect::<Vec<_>>(),ids);assert_eq!(plans[7..].iter().map(|b|b.plan.sectors.len()).sum::<usize>(),34);assert!(!rows.iter().find(|r|r.choice.map_id==506).unwrap().available);
 let probe:Value=serde_json::from_slice(&fs::read(reference_root.join("reference/reference.json")).unwrap()).unwrap();assert_eq!(probe["passed"],6);assert_eq!(probe["failed"],1);let mut negative=0;let mut images=Vec::new();let mut records=Vec::new();let mut failures=Vec::new();let mut rt=Runtime::start_with_menu_skin(i,input("r478-native-menu-skin-binding.json")).unwrap();wait(||{rt.poll();rt.page()==UiPage::Menu});assert!(rt.choice().is_none());
 rt.handle(Action::Select(1,506)).unwrap();assert!(rt.handle(Action::Enter).is_err()&&rt.frame().is_none());assert_eq!(rt.choice().unwrap().map_id,506);negative+=1;
 for(k,id)in ids.iter().copied().enumerate(){let r=probe["results"].as_array().unwrap().iter().find(|r|r["map_id"]==id).unwrap();let next=ids[(k+1)%ids.len()];rt.handle(Action::Select(1,id)).unwrap();rt.handle(Action::Enter).unwrap();wait(||{rt.poll();rt.page()==UiPage::Preview});let mut held:Option<UiFrame>=None;
  for reference in r["images"].as_array().unwrap(){let c=&reference["camera"];let(cx,cy)=(c[0].as_i64().unwrap() as i32,c[1].as_i64().unwrap() as i32);let current=rt.frame().unwrap().camera();if(current.x,current.y)!=(cx,cy){rt.handle(Action::Pan(cx-current.x,cy-current.y)).unwrap();wait(||{rt.poll();!rt.pan_pending()});}if let Some(old)=held.take(){assert!(old.bgra().is_err());negative+=1;}let f=rt.frame().unwrap();assert_eq!(f.identity(),(1,id));assert_eq!((f.camera().x,f.camera().y),(cx,cy));let name=reference["name"].as_str().unwrap();let image=save(&root.join(format!("cpu-{id}-{name}.png")),&f);assert_eq!(pixels(Path::new(image["path"].as_str().unwrap())),pixels(Path::new(reference["image"]["path"].as_str().unwrap())));images.push(json!({"map_id":id,"name":name,"camera":c,"image":image}));held=Some(f);}
  let bounds=&r["bounds"];for(dx,dy,x,y)in[(i32::MIN,i32::MIN,bounds[0].as_i64().unwrap() as i32,bounds[1].as_i64().unwrap() as i32),(i32::MAX,i32::MAX,bounds[2].as_i64().unwrap() as i32-800,bounds[3].as_i64().unwrap() as i32-600)]{rt.handle(Action::Pan(dx,dy)).unwrap();wait(||{rt.poll();!rt.pan_pending()});let c=rt.frame().unwrap().camera();assert_eq!((c.x,c.y),(x,y));negative+=1;}
  let produced=rt.progress().frames_produced.load(Ordering::Acquire);rt.handle(Action::Pan(-48,-24)).unwrap();wait(||rt.progress().frames_produced.load(Ordering::Acquire)>produced);let old=rt.frame().unwrap();let stale=rt.stale_results_rejected;rt.handle(Action::Select(1,next)).unwrap();assert!(old.bgra().is_err());rt.poll();assert_eq!(rt.stale_results_rejected,stale+1);assert!(rt.frame().is_none());negative+=2;
  rt.handle(Action::Select(1,id)).unwrap();let produced=rt.progress().frames_produced.load(Ordering::Acquire);rt.handle(Action::Enter).unwrap();wait(||rt.progress().frames_produced.load(Ordering::Acquire)>produced);let stale=rt.stale_results_rejected;rt.handle(Action::Select(1,next)).unwrap();rt.poll();assert_eq!(rt.stale_results_rejected,stale+1);assert!(rt.frame().is_none());negative+=1;
  rt.handle(Action::Select(1,id)).unwrap();rt.handle(Action::Enter).unwrap();wait(||rt.progress().load_active.load(Ordering::Acquire));rt.handle(Action::Back).unwrap();rt.handle(Action::Select(1,next)).unwrap();wait(||!rt.progress().load_active.load(Ordering::Acquire));rt.poll();assert_eq!(rt.choice().unwrap().map_id,next);assert!(rt.frame().is_none());negative+=1;
  records.push(json!({"map_id":id,"shape":r["shape"],"sectors":plans[7+k].plan.sectors.len(),"anchor":r["anchor"],"bounds":r["bounds"],"budget":r["budget"],"seam":r["seam"],"object_depths":r["object_depths"],"actual_load_and_five_player_frames":true,"queued_load_and_pan_cross_map_rejected":true,"actual_load_Back_cancel_switch_no_frame":true}));
 }
 let stale=rt.stale_results_rejected;assert_eq!(stale,12);close(&mut rt);
 for(k,id)in ids.iter().copied().enumerate(){let idx=7+k;let original=&m["bindings"][idx];let sectors=original["sectors"].as_array().unwrap();let absent=sectors.len()-1;let missing_root=root.join(format!("missing-native-{id}"));fs::create_dir_all(missing_root.join(id.to_string())).unwrap();let mut missing=m.clone();missing["bindings"][idx]["map_root"]=json!(missing_root);for(n,s)in sectors.iter().enumerate(){let old=Path::new(s["pin"]["path"].as_str().unwrap());let dest=missing_root.join(id.to_string()).join(old.file_name().unwrap());if n!=absent{fs::copy(old,&dest).unwrap();}missing["bindings"][idx]["sectors"][n]["pin"]["path"]=json!(dest);}let status=failed(fixture(&root,&missing,&format!("missing-{id}.json")),id);failures.push(json!({"map_id":id,"shape":records[k]["shape"],"kind":"missing_last_necessary_sector_after_other_sectors","missing_source_key":[sectors[absent]["x"],sectors[absent]["y"]],"status":status,"selected_map_retained":true,"no_fallback_frame":true}));negative+=1;let mut incomplete=m.clone();incomplete["bindings"][idx]["sectors"].as_array_mut().unwrap().pop();assert!(native_multisector_resources::load(&fixture(&root,&incomplete,&format!("incomplete-{id}.json"))).unwrap_err().to_string().contains("incomplete"));negative+=1;}
 let diag:Value=serde_json::from_slice(&fs::read(reference_root.join("map506-diagnostic.json")).unwrap()).unwrap();let src:Value=serde_json::from_slice(&fs::read(p.join("logs/continuation-20261003/r481-resource-input.json")).unwrap()).unwrap();let b=src["batch"].as_array().unwrap().iter().find(|b|b["map_id"]==506).unwrap();let mut current=m.clone();let mut plan=b.clone();plan["canonical_sha256"]=diag["canonical_sha256"].clone();current["bindings"].as_array_mut().unwrap().push(plan.clone());
 let mut supported=Runtime::start(fixture(&root,&current,"current-506-effect-tiles.json")).unwrap();wait(||{supported.poll();supported.page()==UiPage::Menu});supported.handle(Action::Select(1,506)).unwrap();supported.handle(Action::Enter).unwrap();wait(||{supported.poll();assert!(!supported.status().contains("載入失敗"),"current supported506 load failed: {}",supported.status());supported.page()==UiPage::Preview});let frame=supported.frame().unwrap();assert_eq!(frame.identity(),(1,506));assert_eq!(frame.bgra().unwrap().len(),800*600*4);let supported_image=save(&root.join("current-506-effect-tiles.png"),&frame);close(&mut supported);assert!(frame.bgra().is_err());
 unknown_tile_archives(&root,&mut plan);*current["bindings"].as_array_mut().unwrap().last_mut().unwrap()=plan;let status=failed(fixture(&root,&current,"unknown255-506.json"),506);assert!(status.contains("block type 255"),"unexpected refusal: {status}");failures.push(json!({"map_id":506,"kind":"synthetic_unknown255_tiles_with_original_complete_geometry","status":status,"no_partial_or_fallback_frame":true}));negative+=1;
 let d=json!({"state":"CURRENT_SIX_NATIVE_MAPS_AND_SUPPORTED506_UNKNOWN255_REFUSAL_VERIFIED","original_six_map_ids":ids,"original_complete_sectors":34,"baseline_catalog_previews":13,"baseline_unqualified":27,"negative_cases":negative,"failure_cases":failures,"map_cases":records,"images":images,"all30_player_frames_match_fixed_R480_independent_reference":true,"cross_map_queued_load_and_pan_rejections":stale,"six_actual_load_Back_cancel_switch_cases":true,"actual_worker_retired":true,"product_runtime_source_changed_in_this_fix":false,"current506_preview":{"image":supported_image,"frame_retired_after_close":true,"independent_full506_pixel_oracle":false},"unknown255_refusal_uses_synthetic_archive_bytes":true,"GUI":0,"whole_game_complete":false});fs::write(root.join("multisector-batch-details.json"),serde_json::to_vec_pretty(&d).unwrap()).unwrap();
